function sectionTitle(sheet,title,description){sheet.replaceChildren(node('h2',title));if(description)sheet.append(node('p',description));}
function renderNews(target){
  if(!target){document.querySelectorAll('.bulletin').forEach(bar=>renderNews(bar));return;}
  const bar=target;
  const isFlash=bar.dataset.newsKind==='flash';
  const isLatest=bar.dataset.newsKind==='latest';
  const validFlash=(Array.isArray(schoolData?.flashNews)?schoolData.flashNews:[]).filter(n=>n&&n.title&&n.title.trim()&&!String(n.id).startsWith('somaram-welcome-'));
  const validNotices=(Array.isArray(schoolData?.notices)?schoolData.notices:[]).filter(n=>n&&n.title&&n.title.trim()&&!String(n.id).startsWith('somaram-welcome-'));
  let items=isFlash?validFlash:(isLatest?validNotices:(validNotices.length?validNotices:validFlash));

  if(!items.length){
    bar.style.display='none';
    bar.replaceChildren();
    return;
  }

  if(isLatest&&bar.previousElementSibling?.classList.contains('model-flash-news')&&bar.previousElementSibling.style.display!=='none'){
    const prev=validFlash.map(x=>x.title).join('|'),cur=validNotices.map(x=>x.title).join('|');
    if(prev===cur){bar.style.display='none';bar.replaceChildren();return;}
  }

  bar.style.display='flex';
  const paused=bar.dataset.newsPaused==='true';
  bar.replaceChildren(node('b',isFlash?'FLASH NEWS':'LATEST NEWS'));
  bar.setAttribute('aria-label',isFlash?'Flash News':'Latest News');
  const window=node('div',null,'news-window'),track=node('div',null,'news-track');
  track.style.animationPlayState=paused?'paused':'running';
  const mapped=items.map(n=>({title:n.title,href:'#notices'}));
  for(let repeat=0;repeat<2;repeat++){
    const group=node('div',null,'news-group');
    if(repeat)group.setAttribute('aria-hidden','true');
    for(const item of mapped)group.append(link(item.title,item.href),node('span','✦'));
    track.append(group);
  }
  window.append(track);
  const pause=node('button',paused?'▶':'Ⅱ','news-pause');
  pause.type='button';
  pause.setAttribute('aria-label',paused?'Resume news scrolling':'Pause news scrolling');
  pause.setAttribute('aria-pressed',String(paused));
  pause.addEventListener('click',()=>{bar.dataset.newsPaused=String(!paused);renderNews(bar);});
  bar.append(window,pause);
}
