function startSchoolMotion(){const layer=node('div',null,'school-sparkle-layer');layer.setAttribute('aria-hidden','true');for(let i=0;i<28;i++){const star=node('i');star.style.left=((i*37+3)%100)+'%';star.style.top=((i*23+7)%100)+'%';star.style.setProperty('--spark-delay',(-i%9)+'s');layer.append(star);}for(let i=0;i<5;i++){const streak=node('span',null,'school-light-streak');streak.style.left=(8+i*19)+'%';streak.style.top=(5+i*17)+'%';streak.style.setProperty('--streak-delay',(-i*4.7)+'s');streak.style.setProperty('--streak-duration',(14+i*3)+'s');layer.append(streak);}document.body.prepend(layer);const pause=node('button','Ⅱ Pause motion','school-motion-toggle');pause.type='button';pause.setAttribute('aria-pressed','false');pause.addEventListener('click',()=>{const stopped=document.documentElement.classList.toggle('school-motion-paused');pause.textContent=stopped?'▶ Resume motion':'Ⅱ Pause motion';pause.setAttribute('aria-pressed',String(stopped));});document.body.append(pause);if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const observer=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){e.target.classList.add('text-entered');observer.unobserve(e.target);}},{threshold:.08});const decorate=()=>document.querySelectorAll('main h2,main h3,main h4,main p').forEach((el,i)=>{if(el.closest('.admission-seats,.hero,.admin-form')||el.dataset.motionReady)return;el.dataset.motionReady='true';el.classList.add('school-text-reveal');el.style.setProperty('--text-delay',(i%4*.06)+'s');observer.observe(el);});decorate();new MutationObserver(decorate).observe(document.querySelector('main'),{childList:true,subtree:true});document.addEventListener('visibilitychange',()=>document.documentElement.classList.toggle('school-motion-hidden',document.hidden));}
startSchoolMotion();

let homeGalleryTimer;
function startHomePhotoSlider(){clearInterval(homeGalleryTimer);const art=document.querySelector('.hero .illustration'),photos=[...(schoolData.gallery||[])].sort((a,b)=>Number(/^achievements?$/i.test(b.category||''))-Number(/^achievements?$/i.test(a.category||'')));if(!art||!photos.length)return;const viewport=node('div',null,'home-gallery-viewport'),track=node('div',null,'home-gallery-track');viewport.setAttribute('aria-label','School photo slideshow');for(const [i,photo]of [...photos,photos[0]].entries()){const img=node('img');img.src=photo.src;img.alt=photo.title||'School photo';img.loading=i<2?'eager':'lazy';img.decoding='async';track.append(img);}viewport.append(track);const caption=node('small',photos[0].title),button=node('button','Ⅱ Pause photos','home-gallery-pause');button.type='button';button.setAttribute('aria-pressed','false');let index=0,paused=false,hover=false;button.addEventListener('click',()=>{paused=!paused;button.textContent=paused?'▶ Play photos':'Ⅱ Pause photos';button.setAttribute('aria-pressed',String(paused));});viewport.addEventListener('mouseenter',()=>hover=true);viewport.addEventListener('mouseleave',()=>hover=false);viewport.addEventListener('focusin',()=>hover=true);viewport.addEventListener('focusout',()=>hover=false);art.replaceChildren(viewport,caption,button);if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;homeGalleryTimer=setInterval(()=>{if(!art.isConnected){clearInterval(homeGalleryTimer);return;}if(paused||hover||document.hidden||document.documentElement.classList.contains('school-motion-paused'))return;index++;track.style.transition='transform 1s ease-in-out';track.style.transform='translateX(-'+index*100+'%)';caption.textContent=photos[index%photos.length].title||'School photo';if(index===photos.length)setTimeout(()=>{if(!track.isConnected)return;track.style.transition='none';track.style.transform='translateX(0)';index=0;},1050);},3000);}
function addTextSizeControls(){let scale=1;try{scale=Math.max(.85,Math.min(1.3,Number(localStorage.getItem('somaram-text-scale'))||1));}catch{}const controls=node('div',null,'text-size-controls');controls.setAttribute('role','group');controls.setAttribute('aria-label','Text size');controls.append(node('span','Text Size:'));const apply=()=>{const items=[...document.querySelectorAll('.brand h1,.brand p,#menu a,main h2,main h3,main h4,main p,main .resource,main th,main td,main label,main input,main button,main strong,footer p')];for(const el of items)if(!el.dataset.baseFont)el.dataset.baseFont=parseFloat(getComputedStyle(el).fontSize);for(const el of items)el.style.fontSize=(Number(el.dataset.baseFont)*scale)+'px';};for(const [text,label,value]of [['A−','Decrease text size',-.1],['A','Reset text size',0],['A+','Increase text size',.1]]){const button=node('button',text);button.type='button';button.setAttribute('aria-label',label);button.addEventListener('click',()=>{scale=value?Math.max(.85,Math.min(1.3,Math.round((scale+value)*100)/100)):1;try{localStorage.setItem('somaram-text-scale',String(scale));}catch{}apply();});controls.append(button);}document.querySelector('.top').append(controls);if(scale!==1)apply();new MutationObserver(()=>{if(scale!==1)apply();}).observe(document.querySelector('main'),{subtree:true,childList:true});}
addTextSizeControls();

function renderHeaderActions(){let actions=document.querySelector('.header-quick-actions');if(!actions){actions=node('nav',null,'header-quick-actions');actions.setAttribute('aria-label','School quick actions');document.querySelector('.brand').after(actions);}actions.replaceChildren(link('194 Schools','#directory','header-quick'),link('Student Portal','#portal','header-quick'),link('Apply ↗','#admissions','header-quick header-apply'),link('Gemini ↗','https://gemini.google.com/','header-ai'),link('ChatGPT ↗','https://chatgpt.com/','header-ai'));}
async function schoolDirectoryPage(sheet){sectionTitle(sheet,'194 Telangana Model Schools','Search school locations, districts and mandals from the 194-school reference PDF.');const sourceLinks=node('div',null,'actions');sourceLinks.append(link('Download source PDF','/downloads/telangana-model-schools-194-source.pdf','resource'),link('Download school list (CSV)','/downloads/telangana-model-schools-194.csv','resource'),link('Government UDISE report ↗','https://schooledu.telangana.gov.in/UDISE/totalSchoolReport.do','resource'));sheet.append(sourceLinks);const input=node('input');input.type='search';input.placeholder='Search school / district / mandal';input.setAttribute('aria-label','Search school directory');sheet.append(input);const list=node('div',null,'book-grid'),count=node('p');sheet.append(count,list);try{const schools=await(await fetch('data/school-directory.json').catch(()=>fetch('/data/school-directory.json'))).json();if(!sheet.isConnected)return;const fill=()=>{const filtered=schools.filter(s=>[s.name,s.district,s.mandal,s.sourceDistrict,s.sourceMandal,s.sourceLocation].join(' ').toLowerCase().includes(input.value.toLowerCase()));count.textContent=filtered.length+' of '+schools.length+' schools';list.replaceChildren(...filtered.map(s=>{const card=node('article',null,'resource');card.append(node('h3',s.serial+'. '+s.name),node('p','Mandal: '+s.mandal+' · District: '+s.district));if(s.website)card.append(link('Visit school website ↗',s.website,'resource'));if(s.sourceDistrict.toLowerCase()!==s.district.toLowerCase()||s.sourceMandal.toLowerCase()!==s.mandal.toLowerCase())card.append(node('small','PDF label: '+s.sourceMandal+' · '+s.sourceDistrict));return card;}));};input.addEventListener('input',fill);fill();}catch{list.append(link('Official Telangana Model Schools Portal ↗','https://telanganams.cgg.gov.in/TGMSWEB20/#/','resource'));}}
function campusFacilitiesPage(sheet){sectionTitle(sheet,'Campus & Learning Spaces','Photographs supplied by TGMS Somaram.');const grid=node('div',null,'gallery-grid');const photos=(schoolData.gallery||[]).filter(p=>p.gallery_type==='campus'||/campus|courtyard|building|ground|entrance|gate|classroom|lab/i.test((p.category||'')+' '+(p.title||'')));for(const p of photos)grid.append(photoCard(p));sheet.append(grid,node('h3','Vocational Learning'),node('p','Media and Entertainment · Health Care'),link('View all school photographs','#gallery','resource'));}

function inquiryCopyControls(form,inputs,fields){
 let saved=null;
 const actions=node('div',null,'actions');
 const preview=node('button','Print Preview / ప్రింట్ ప్రివ్యూ','action secondary');preview.type='button';
 const download=node('button','Download Copy (.html) / డౌన్‌లోడ్','action secondary');download.type='button';
 actions.append(preview,download);form.append(actions,node('p','Preview or download your entered details before submitting. A draft has no saved reference. To save a PDF, open Print Preview and choose Print / Save as PDF.','inquiry-copy-help'));
 function snapshot(){return saved||{data:Object.fromEntries(Object.entries(inputs).map(([key,input])=>[key,input.value.trim()])),reference:null};}
 function receipt(copy){const section=node('section',null,'inquiry-receipt');section.append(node('h1','TGMS Somaram'),node('h2','Admission Inquiry — Student Copy'),node('p',copy.reference?'Saved inquiry reference: '+copy.reference:'DRAFT — Not submitted to the school'),node('p','This is a school inquiry, not an official TGMSCET application or admission confirmation. Complete the official application separately through CGG.'));const list=node('dl');for(const [key,label]of fields){list.append(node('dt',label.replace(' (optional)','')),node('dd',copy.data[key]||'—'));}section.append(list,node('p','Keep this copy privately. For corrections or follow-up, contact the school office.'));return section;}
 preview.addEventListener('click',()=>{const dialog=node('dialog',null,'inquiry-preview');const page=receipt(snapshot());const buttons=node('div',null,'actions inquiry-preview-actions');const print=node('button','Print / Save as PDF','action');print.type='button';const close=node('button','Close','action secondary');close.type='button';print.addEventListener('click',()=>{document.querySelectorAll('body>.inquiry-print-sheet').forEach(el=>el.remove());const printable=page.cloneNode(true);printable.classList.add('inquiry-print-sheet');document.body.append(printable);document.body.classList.add('printing-inquiry');window.print();document.body.classList.remove('printing-inquiry');printable.remove();});close.addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>dialog.remove());buttons.append(print,close);dialog.append(page,buttons);document.body.append(dialog);dialog.showModal();});
 download.addEventListener('click',()=>{const copy=snapshot();const html='<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TGMS Somaram — Student Inquiry Copy</title><style>body{font:16px Arial,sans-serif;max-width:760px;margin:32px auto;padding:16px;color:#173e78}h1,h2{line-height:1.3}dt{font-weight:bold;margin-top:14px}dd{margin:4px 0;white-space:pre-wrap;overflow-wrap:anywhere}@media print{body{margin:0;color:#000}}</style><body>'+receipt(copy).outerHTML+'</body></html>';const url=URL.createObjectURL(new Blob([html],{type:'text/html;charset=utf-8'}));const a=node('a');a.href=url;a.download='TGMS-Somaram-Inquiry-'+(copy.reference?'Saved':'Draft')+'.html';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);});
 form.addEventListener('input',()=>{saved=null;});
 return {saved(data,reference){saved={data:{...data},reference};}};
}
function admissionInquiryForm(sheet){const steps=node('div',null,'admission-steps');for(const [title,body]of [['STEP 01 · TGMSCET','Check the current official notification for entrance-test eligibility and dates.'],['STEP 02 · Merit & Reservation','Selection follows the current government admission and reservation rules.'],['STEP 03 · Document Verification','The school office confirms the documents required after selection.']]){const c=node('article',null,'resource');c.append(node('h3',title),node('p',body));steps.append(c);}sheet.append(steps);const form=node('form',null,'admission-inquiry-form');form.append(node('h2','Online Admission Inquiry & Preliminary Registration Form'),node('p','Register your interest with TGMS Somaram. This is a school inquiry, not an official TGMSCET application or admission confirmation. Complete the official application separately through CGG.'));const grid=node('div',null,'inquiry-fields'),inputs={};const fields=[['studentName','Student Full Name','text',true],['dob','Date of Birth','date',true],['gender','Gender','select',true],['targetClass','Class Seeking Admission','select',true],['casteCategory','Community / Category (optional)','select',false],['fatherName','Parent / Guardian Name','text',true],['motherName','Mother Name (optional)','text',false],['phone','Parent Mobile Number','tel',true],['email','Email (optional)','email',false],['previousSchool','Previous School (optional)','text',false],['address','Address','textarea',true]];for(const [key,label,type,required]of fields){const input=field(grid,label,'',type==='select'?'text':type);if(type==='select'){const select=node('select');select.id=input.id;input.replaceWith(select);const values=key==='gender'?['Select','Male','Female','Other']:key==='targetClass'?['Select','Class VI','Class VII','Class VIII','Class IX','Class X','Intermediate First Year']:['Not specified','SC','ST','BC-A','BC-B','BC-C','BC-D','BC-E','OC','Other'];for(const value of values){const option=node('option',value);option.value=value==='Select'?'':value;select.append(option);}inputs[key]=select;}else inputs[key]=input;inputs[key].required=required;if(key==='dob')inputs[key].max=indiaToday();if(key==='phone'){input.pattern='[0-9]{10}';input.maxLength=10;}if(key==='address')input.maxLength=600;else if(type!=='select')input.maxLength=200;}form.append(grid);const consentLabel=node('label',null,'inquiry-consent'),consent=node('input');consent.type='checkbox';consent.required=true;consentLabel.append(consent,document.createTextNode(' I consent to sharing these details privately with the school for admission follow-up. Do not enter Aadhaar, bank details or upload identity documents.'));form.append(consentLabel);const button=submitButton(form,'Submit School Inquiry'),status=statusNode(form);const studentCopy=inquiryCopyControls(form,inputs,fields);let requestId=crypto.randomUUID();form.addEventListener('submit',async e=>{e.preventDefault();button.disabled=true;const data=Object.fromEntries(Object.entries(inputs).map(([k,input])=>[k,input.value.trim()]));try{const result=await jsonRequest('/api/admissions',{...data,consent:consent.checked,requestId});status.textContent='Inquiry saved. Reference: '+result.appNumber+'. The school will follow up. Official CGG application is separate.';studentCopy.saved(data,result.appNumber);form.reset();requestId=crypto.randomUUID();}catch(error){status.textContent=error.message;}finally{button.disabled=false;}});sheet.append(form);}
function admissionInbox(sheet){const card=node('section',null,'admin-form');card.append(node('h3','Private Admission Inquiries'));const button=node('button','Load admission inquiries');button.type='button';const list=node('div');button.onclick=async()=>{button.disabled=true;try{const r=await fetch('/api/admin/admission-inquiries',{cache:'no-store'});const data=await r.json();if(!r.ok)throw Error(data.error||'Login required');list.replaceChildren(node('p',data.inquiries.length+' inquiries'));for(const item of data.inquiries){const entry=node('article',null,'resource');entry.append(node('h4',item.studentName+' · '+item.targetClass),node('p',item.fatherName+' · '+item.phone),node('p','DOB: '+item.dob+' · '+item.gender+' · '+item.casteCategory),node('p',item.address),node('small',item.id+' · '+item.submittedAt));list.append(entry);}}catch(error){list.textContent=error.message;}finally{button.disabled=false;}};card.append(button,list);sheet.append(card);}

for(const locale of Object.keys(text))text[locale].privacyBody='Admission inquiry details are stored privately for authorized TGMS Somaram administrators to follow up with families. This school inquiry does not replace the official CGG application. Do not submit Aadhaar, bank information or identity documents. External educational websites follow their own privacy policies. Contact the school to request corrections or removal of an inquiry.';
